(function(){
 function ap(){
  if(typeof FSTEPS==='undefined'||!FSTEPS.desinf||typeof FLOWS==='undefined')return false;
  const s=FSTEPS.desinf;
  if(s[0])s[0][1]='Entrada do desinfetante pelo conector 85 (galão). Anotação na folha ao lado do 85: Puristeril, o desinfetante aspirado.';
  if(s[1])s[1][1]='Passa pelo S115, o sensor da válvula de desinfecção. Anotação na folha: "validar o desinfetante", com um valor entre parênteses que não deu para ler.';
  const f=FLOWS.find(x=>x.id==='desinf');
  if(f&&f.d&&f.d.indexOf('Puristeril')<0){f.d+=' O produto, na folha, é o Puristeril.';const b=document.querySelector('#mflows .fl[data-f="desinf"]');if(b)b.title=f.d}
  return true}
 let n=0;const t=setInterval(()=>{ap();if(++n>=24)clearInterval(t)},250);ap();
})();

})();}catch(e){console.error("pacote",e);}
try{(function(){
/* Desinfecção química em duas etapas: sucção do desinfetante (1/2) e preparação (2/2) */
(function(){
 if(window.__enc)return;window.__enc=1;
 const N={desinf:'Desinfecção química 1/2: sucção do desinfetante',dprep:'Desinfecção química 2/2: preparação'};
 const TXT={desinf:['Etapa 1 de 2','Depois da sucção do desinfetante vem a preparação.','dprep','Continuar: preparação (etapa 2) →'],
            dprep:['Etapa 2 de 2','Esta etapa vem depois da sucção do desinfetante.','desinf','← Voltar: sucção do desinfetante (etapa 1)']};
 function nomes(){
  if(typeof FLOWS==='undefined')return;
  Object.keys(N).forEach(id=>{const f=FLOWS.find(x=>x.id===id);if(!f)return;f.n=N[id];
   const b=document.querySelector('#mflows .fl[data-f="'+id+'"]');
   if(b&&b.lastChild&&b.lastChild.nodeType===3)b.lastChild.textContent=N[id];else if(b&&b.lastChild&&b.lastChild.nodeType!==3&&!b.querySelector('i'))b.textContent=N[id]});
  const a=document.querySelector('#mflows .fl[data-f="desinf"]'),c=document.querySelector('#mflows .fl[data-f="dprep"]');
  if(a&&c&&a.nextElementSibling!==c)a.after(c)}
 function cadeia(){
  const cap=document.getElementById('mpanel');if(!cap||typeof flowSel==='undefined'||!TXT[flowSel])return;
  if(cap.querySelector('.fchain'))return;const t=TXT[flowSel];
  const d=document.createElement('div');d.className='fchain';
  d.innerHTML='<b>'+t[0]+'</b> · '+t[1]+' <button class="sm" data-chain="'+t[2]+'">'+t[3]+'</button>';
  const h=cap.querySelector('h3');if(h)h.after(d);else cap.prepend(d)}
 if(typeof fRender==='function'){const o=fRender;fRender=function(){const r=o.apply(this,arguments);try{nomes();cadeia()}catch(_){}return r}}
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-chain]');if(!b)return;ev.preventDefault();flowShow(b.dataset.chain)});
 let n=0;const t=setInterval(()=>{nomes();if(++n>=24)clearInterval(t)},250);nomes();
})();

})();}catch(e){console.error("pacote",e);}
try{(function(){
/* Calibração: todas as calibrações do capítulo 9 numa lista só, item por item, tudo visível */
(function(){
 if(window.__calflat)return;window.__calflat=1;
 const CH=[['Pressão arterial','9.1.3'],['Bomba de sangue arterial (EBM)','9.1.4'],['Pressão venosa','9.1.6'],['Venosa no detector de ar','9.1.7'],['Taxa da bomba de sangue','9.1.8'],['Unipunção','9.1.11'],['Volume da bomba UF','9.1.12'],['Desgaseificação','9.1.13'],['Fluxo 300','9.1.14'],['Fluxo 500','9.1.17'],['Fluxo 800','9.1.18'],['Temperatura','9.1.19'],['Sistema de mistura','9.1.23'],['Condutividade','9.1.31'],['Pressão do dialisante','9.1.38'],['Vazamento de sangue','9.1.42'],['Bibag','9.1.43'],['Registro de falhas','9.1.44'],['NOVRAM','9.1.45'],['Bomba de heparina','9.1.46'],['Unidade hidráulica','9.2'],['Detector de ar','9.3']];
 const code=a=>{const c=a.querySelector('.code');return c?c.textContent.trim():''};
 function flat(){
  const L=document.getElementById('clist');if(!L)return;
  const arts=[...L.querySelectorAll('article.it')];
  arts.forEach(a=>{
   a.querySelectorAll(':scope>.trw,:scope>.tw0').forEach(x=>x.remove());
   a.querySelectorAll('.hd .tag.sub').forEach(x=>x.remove());
   a.hidden=false;a.style.marginLeft='';a.classList.remove('par');a.classList.add('cf');
   const d=+a.dataset.dp||0;a.classList.toggle('cf0',d===0);a.classList.toggle('cf2',d>=2)});
  const p=document.querySelector('#t-cal .cnt');
  if(p){const n=arts.filter(a=>+a.dataset.dp>0).length;
   p.textContent='Capítulo 9 do manual: '+(arts.length?n+' calibrações e ajustes':'nenhum resultado')+', todos nesta lista. Toque num item para ver as páginas originais, com fluxogramas e displays, sem alterações.'}}
 function chips(){
  if(document.getElementById('cfchips'))return;
  const L=document.getElementById('clist');if(!L)return;
  const d=document.createElement('div');d.id='cfchips';d.setAttribute('aria-label','Ir direto para uma calibração');
  d.innerHTML=CH.map(c=>'<button type="button" data-c="'+c[1]+'">'+c[0]+'</button>').join('');
  L.parentNode.insertBefore(d,L);
  d.addEventListener('click',ev=>{const b=ev.target.closest('button[data-c]');if(!b)return;
   let a=[...L.querySelectorAll('article.it')].find(x=>code(x)===b.dataset.c);
   if(!a){const q=document.getElementById('cq');if(q&&q.value){q.value='';q.dispatchEvent(new Event('input',{bubbles:true}))}
    a=[...L.querySelectorAll('article.it')].find(x=>code(x)===b.dataset.c)}
   if(!a)return;const h=a.querySelector('.hd');if(h&&h.getAttribute('aria-expanded')!=='true')h.click();
   setTimeout(()=>a.scrollIntoView({behavior:"smooth",block:"start"}),150)})}
 if(typeof secRender==='function'){const prev=secRender;secRender=function(k){const r=prev.apply(this,arguments);if(k==='cal'){try{flat()}catch(e){console.error(e)}}return r}}
 chips();flat();
})();

})();}catch(e){console.error("pacote",e);}
